package com.aftermarket.backend;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.boot.context.properties.ConfigurationPropertiesScan;
import org.springframework.scheduling.annotation.EnableScheduling;

// org.kie.kogito.** is scanned so the beans generated by kogito-maven-plugin (processes, user tasks) are picked up
@SpringBootApplication(scanBasePackages = { "com.aftermarket.backend", "org.kie.kogito.**" })
@ConfigurationPropertiesScan
@EnableScheduling
public class BackendApplication {

    public static void main(String[] args) {
        SpringApplication.run(BackendApplication.class, args);
    }
}
